/* Build a ClientHello: record sequence, message sequence, session ID length, cookie, and
   the first byte of the random. Returns the record length.  */
static UINT clienthello_build(UCHAR *buffer, USHORT sequence_high, ULONG sequence_low, UINT message_sequence,
                              UINT session_id_length, const UCHAR *cookie, UINT cookie_length, UCHAR random_first)
{
UINT body_length = 35 + session_id_length + 1 + cookie_length + sizeof(clienthello_suites);
UINT position;

    buffer[0] = 0x16;
    buffer[1] = 0xfe;
    buffer[2] = 0xfd;
    buffer[3] = 0;
    buffer[4] = 0;
    buffer[5] = (UCHAR)(sequence_high >> 8);
    buffer[6] = (UCHAR)sequence_high;
    buffer[7] = (UCHAR)(sequence_low >> 24);
    buffer[8] = (UCHAR)(sequence_low >> 16);
    buffer[9] = (UCHAR)(sequence_low >> 8);
    buffer[10] = (UCHAR)sequence_low;
    buffer[11] = (UCHAR)((body_length + 12) >> 8);
    buffer[12] = (UCHAR)(body_length + 12);
    buffer[13] = 0x01;
    buffer[14] = 0;
    buffer[15] = (UCHAR)(body_length >> 8);
    buffer[16] = (UCHAR)body_length;
    buffer[17] = (UCHAR)(message_sequence >> 8);
    buffer[18] = (UCHAR)message_sequence;
    buffer[19] = 0;
    buffer[20] = 0;
    buffer[21] = 0;
    buffer[22] = 0;
    buffer[23] = (UCHAR)(body_length >> 8);
    buffer[24] = (UCHAR)body_length;
    buffer[25] = 0xfe;
    buffer[26] = 0xfd;
    memcpy(&buffer[27], clienthello_random, sizeof(clienthello_random));
    buffer[27] = random_first;
    buffer[59] = (UCHAR)session_id_length;
    memset(&buffer[60], 0xA5, session_id_length);
    position = 60 + session_id_length;
    buffer[position] = (UCHAR)cookie_length;
    position++;
    memcpy(&buffer[position], cookie, cookie_length);
    position += cookie_length;
    memcpy(&buffer[position], clienthello_suites, sizeof(clienthello_suites));
    position += sizeof(clienthello_suites);

    return(position);
}

/* HMAC-SHA256 computed with the crypto library's HMAC method, independently of the
   server's own construction.  */
static VOID hmac_sha256(const UCHAR *key, UINT key_length, UCHAR *data, UINT length, UCHAR *output)
{
UINT status;

    status = crypto_method_hmac_sha256.nx_crypto_operation(NX_CRYPTO_AUTHENTICATE, NX_NULL, &crypto_method_hmac_sha256,
                                                           (UCHAR *)key, key_length << 3, data, length, NX_NULL,
                                                           output, 32, hmac_metadata, sizeof(hmac_metadata),
                                                           NX_NULL, NX_NULL);
    if (status)
    {
        ERROR_COUNTER();
    }
}

/* The cookie expected for a ClientHello: key identifier, then HMAC-SHA256 under secret of
   the peer address and ports, the ClientHello fields up to the session ID, and the cipher
   suite and compression lists.  */
static VOID cookie_expected(const UCHAR *secret, UCHAR key_id, NXD_ADDRESS *address, UINT remote_port,
                            UINT local_port, const UCHAR *clienthello, UCHAR *cookie)
{
UCHAR data[1 + 16 + 4 + 35 + 32 + CLIENTHELLO_MAX];
UCHAR mac[32];
UINT  length = 0;
UINT  session_id_length = clienthello[59];
UINT  suites_offset;
UINT  suites_end;
UINT  i;

    data[length++] = (UCHAR)address -> nxd_ip_version;
    if (address -> nxd_ip_version == NX_IP_VERSION_V6)
    {
        for (i = 0; i < 4; i++)
        {
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 24);
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 16);
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 8);
            data[length++] = (UCHAR)address -> nxd_ip_address.v6[i];
        }
    }
    else
    {
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 24);
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 16);
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 8);
        data[length++] = (UCHAR)address -> nxd_ip_address.v4;
    }
    data[length++] = (UCHAR)(remote_port >> 8);
    data[length++] = (UCHAR)remote_port;
    data[length++] = (UCHAR)(local_port >> 8);
    data[length++] = (UCHAR)local_port;

    memcpy(&data[length], &clienthello[25], 35 + session_id_length);
    length += 35 + session_id_length;

    suites_offset = 61 + session_id_length + clienthello[60 + session_id_length];
    suites_end = suites_offset + 2 + (((UINT)clienthello[suites_offset] << 8) | clienthello[suites_offset + 1]);
    suites_end += 1 + clienthello[suites_end];
    memcpy(&data[length], &clienthello[suites_offset], suites_end - suites_offset);
    length += suites_end - suites_offset;

    hmac_sha256(secret, 32, data, length, mac);
    cookie[0] = key_id;
    memcpy(&cookie[1], mac, NX_SECURE_DTLS_COOKIE_LENGTH - 1);
}

/* Present a datagram to the server's cookie check as the receive callback would: a UDP
   header, then data_length bytes of record, with a packet length extra bytes longer than
   the data actually held.  */
static UINT direct_check(const UCHAR *data, UINT data_length, UINT extra, NXD_ADDRESS *address, UINT remote_port,
                         UINT ip_version, NXD_IPV6_ADDRESS *ipv6_address, NX_SECURE_DTLS_CLIENTHELLO_INFO *hello_info)
{
NX_PACKET *packet_ptr;
UINT       status;

    status = nx_packet_allocate(&direct_pool, &packet_ptr, 0, NX_NO_WAIT);
    if (status)
    {
        ERROR_COUNTER();
        return(status);
    }

    memset(packet_ptr -> nx_packet_prepend_ptr, 0, 8);
    memcpy(packet_ptr -> nx_packet_prepend_ptr + 8, data, data_length);
    packet_ptr -> nx_packet_append_ptr = packet_ptr -> nx_packet_prepend_ptr + 8 + data_length;
    packet_ptr -> nx_packet_length = 8 + data_length + extra;
    packet_ptr -> nx_packet_ip_version = (UCHAR)ip_version;
    if (ip_version == NX_IP_VERSION_V4)
    {
        packet_ptr -> nx_packet_address.nx_packet_interface_ptr = &server_ip.nx_ip_interface[0];
    }
    else
    {
        packet_ptr -> nx_packet_address.nx_packet_ipv6_address_ptr = ipv6_address;
    }

    memset(hello_info, 0, sizeof(NX_SECURE_DTLS_CLIENTHELLO_INFO));
    status = _nx_secure_dtls_server_cookie_check(&dtls_server, packet_ptr, address, remote_port, SERVER_PORT, hello_info);

    nx_packet_release(packet_ptr);

    return(status);
}

/* Send a record from the raw socket to the server.  */
static VOID raw_send(const UCHAR *data, UINT length)
{
NX_PACKET  *packet_ptr;
NXD_ADDRESS server_address;
UINT        status;

    server_address.nxd_ip_version = NX_IP_VERSION_V4;
    server_address.nxd_ip_address.v4 = TEST_SERVER_IP_ADDRESS;

    status = nx_packet_allocate(&client_pool, &packet_ptr, NX_UDP_PACKET, NX_WAIT_FOREVER);
    status |= nx_packet_data_append(packet_ptr, (VOID *)data, length, &client_pool, NX_NO_WAIT);
    status |= nxd_udp_socket_send(&raw_socket, packet_ptr, &server_address, SERVER_PORT);
    if (status)
    {
        ERROR_COUNTER();
    }
}

/* Receive one datagram on the raw socket. Returns its length, or 0 if none arrives.  */
static UINT raw_receive(UCHAR *buffer, UINT size, ULONG wait_option)
{
NX_PACKET *packet_ptr;
ULONG      length = 0;

    if (nx_udp_socket_receive(&raw_socket, &packet_ptr, wait_option) == NX_SUCCESS)
    {
        if (nx_packet_data_extract_offset(packet_ptr, 0, buffer, size, &length))
        {
            ERROR_COUNTER();
        }
        nx_packet_release(packet_ptr);
    }

    return((UINT)length);
}

/* Move the raw socket to another local port.  */
static VOID raw_rebind(UINT port)
{
    nx_udp_socket_unbind(&raw_socket);
    if (nx_udp_socket_bind(&raw_socket, port, NX_NO_WAIT))
    {
        ERROR_COUNTER();
    }
}

/* Check that a reply is a sessionless HelloVerifyRequest echoing the ClientHello's
   sequence numbers, and copy its cookie.  */
static VOID helloverifyrequest_check(const UCHAR *reply, UINT length, const UCHAR *clienthello, UCHAR *cookie)
{
    if ((length != 28 + NX_SECURE_DTLS_COOKIE_LENGTH) ||
        (reply[0] != 0x16) || (reply[1] != 0xfe) || (reply[2] != 0xff) ||
        memcmp(&reply[3], &clienthello[3], 8) ||
        (reply[11] != 0) || (reply[12] != 12 + 3 + NX_SECURE_DTLS_COOKIE_LENGTH) ||
        (reply[13] != NX_SECURE_TLS_HELLO_VERIFY_REQUEST) ||
        (reply[16] != 3 + NX_SECURE_DTLS_COOKIE_LENGTH) ||
        memcmp(&reply[17], &clienthello[17], 2) ||
        (reply[19] != 0) || (reply[20] != 0) || (reply[21] != 0) ||
        (reply[24] != 3 + NX_SECURE_DTLS_COOKIE_LENGTH) ||
        (reply[25] != 0xfe) || (reply[26] != 0xff) || (reply[27] != NX_SECURE_DTLS_COOKIE_LENGTH))
    {
        ERROR_COUNTER();
        memset(cookie, 0, NX_SECURE_DTLS_COOKIE_LENGTH);
        return;
    }

    memcpy(cookie, &reply[28], NX_SECURE_DTLS_COOKIE_LENGTH);
}

/* Send a ClientHello and expect a HelloVerifyRequest; return its cookie.  */
static VOID clienthello_expect_hvr(const UCHAR *clienthello, UINT length, UCHAR *cookie)
{
UCHAR reply[256];
UINT  reply_length;

    raw_send(clienthello, length);
    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    helloverifyrequest_check(reply, reply_length, clienthello, cookie);
}

/* Send a datagram and expect no reply.  */
static VOID datagram_expect_drop(const UCHAR *data, UINT length)
{
UCHAR reply[256];

    raw_send(data, length);
    if (raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE / 5) != 0)
    {
        ERROR_COUNTER();
    }
}

/* Obtain a cookie from the raw socket's port and return it in a second ClientHello with
   the given sequence numbers. The server then allocates a session.  */
static VOID cookie_exchange(USHORT sequence_high, ULONG sequence_low, UINT message_sequence)
{
UCHAR clienthello[CLIENTHELLO_MAX];
UCHAR cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UINT  length;

    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    clienthello_expect_hvr(clienthello, length, cookie);
    length = clienthello_build(clienthello, sequence_high, sequence_low, message_sequence, 0,
                               cookie, NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);
    raw_send(clienthello, length);
}

static VOID server_dtls_setup(VOID)
{
UINT status;

    status = nx_secure_dtls_server_create(&dtls_server, &server_ip, SERVER_PORT, NX_IP_PERIODIC_RATE,
                                          server_session_buffer, sizeof(server_session_buffer),
                                          &nx_crypto_tls_ciphers, server_metadata, sizeof(server_metadata),
                                          server_tls_packet_buffer, sizeof(server_tls_packet_buffer),
                                          server_connect_notify, server_receive_notify);
    if (status)
    {
        ERROR_COUNTER();
    }

    status = nx_secure_dtls_server_notify_set(&dtls_server, server_disconnect_notify, server_error_notify);
    if (status)
    {
        ERROR_COUNTER();
    }

    memset(&server_local_certificate, 0, sizeof(server_local_certificate));
    status = nx_secure_x509_certificate_initialize(&server_local_certificate,
                                                   test_device_cert_der, test_device_cert_der_len,
                                                   NX_NULL, 0, test_device_cert_key_der,
                                                   test_device_cert_key_der_len, NX_SECURE_X509_KEY_TYPE_RSA_PKCS1_DER);
    if (status)
    {
        ERROR_COUNTER();
    }

    status = nx_secure_dtls_server_local_certificate_add(&dtls_server, &server_local_certificate, 1);
    if (status)
    {
        ERROR_COUNTER();
    }
}

/* The optional API that supplies the secret cookie secrets are derived from.  */
static VOID test_secret_set_api(VOID)
{
UCHAR secret[33];

    memset(secret, 0x5A, sizeof(secret));

    if (_nxe_secure_dtls_server_cookie_secret_set(NX_NULL, secret, 32) != NX_PTR_ERROR)
    {
        ERROR_COUNTER();
    }

    if (_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 32) != NX_PTR_ERROR)
    {
        ERROR_COUNTER();
    }

    if (_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, secret, 15) != NX_INVALID_PARAMETERS)
    {
        ERROR_COUNTER();
    }

    if (_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, secret, 33) != NX_INVALID_PARAMETERS)
    {
        ERROR_COUNTER();
    }

    if (_nx_secure_dtls_server_cookie_secret_set(&dtls_server, secret, 33) != NX_INVALID_PARAMETERS)
    {
        ERROR_COUNTER();
    }

    if ((_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, secret, 16) != NX_SUCCESS) ||
        (dtls_server.nx_dtls_server_cookie_master_secret_length != 16) ||
        (dtls_server.nx_dtls_server_cookie_ready != NX_FALSE))
    {
        ERROR_COUNTER();
    }

    if ((_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0) != NX_SUCCESS) ||
        (dtls_server.nx_dtls_server_cookie_master_secret_length != 0) ||
        (dtls_server.nx_dtls_server_cookie_master_secret[0] != 0))
    {
        ERROR_COUNTER();
    }
}

/* Datagrams from an unknown source that are not an unfragmented initial ClientHello are
   dropped without a reply and without a session.  */
static VOID test_drops(VOID)
{
UCHAR clienthello[CLIENTHELLO_MAX];
UINT  length;
UCHAR alert[] = {0x15, 0xfe, 0xfd, 0, 0, 0, 0, 0, 0, 0, 0, 0, 2, 2, 40};
UCHAR application_data[80];

    raw_rebind(RAW_PORT);

    datagram_expect_drop(alert, 5);
    datagram_expect_drop(alert, sizeof(alert));

    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    memcpy(application_data, clienthello, sizeof(application_data));
    application_data[0] = 0x17;
    datagram_expect_drop(application_data, sizeof(application_data));

    /* First fragment of a ClientHello.  */
    clienthello[24] = (UCHAR)(clienthello[24] - 10);
    datagram_expect_drop(clienthello, length - 10);

    /* Epoch 1.  */
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    clienthello[4] = 1;
    datagram_expect_drop(clienthello, length);

    /* Session ID longer than 32 bytes.  */
    length = clienthello_build(clienthello, 0, 0, 0, 33, NX_NULL, 0, 0x32);
    datagram_expect_drop(clienthello, length);

    if ((server_connect_count != 0) ||
        (dtls_server.nx_dtls_server_sessions[0].nx_secure_dtls_session_in_use) ||
        (dtls_server.nx_dtls_server_sessions[1].nx_secure_dtls_session_in_use))
    {
        ERROR_COUNTER();
    }
}

/* More sources than sessions send an initial ClientHello: each is answered with a
   HelloVerifyRequest, and none is given a session.  */
static VOID test_exhaustion(VOID)
{
UCHAR clienthello[CLIENTHELLO_MAX];
UCHAR cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UINT  length;
UINT  i;

    for (i = 0; i < NUM_SERVER_SESSIONS + 4; i++)
    {
        raw_rebind(RAW_PORT + 1 + i);
        length = clienthello_build(clienthello, 0, i, i, 0, NX_NULL, 0, 0x32);
        clienthello_expect_hvr(clienthello, length, cookie);
        if (cookie[0] != dtls_server.nx_dtls_server_cookie_current)
        {
            ERROR_COUNTER();
        }
    }

    if ((server_connect_count != 0) ||
        (dtls_server.nx_dtls_server_sessions[0].nx_secure_dtls_session_in_use) ||
        (dtls_server.nx_dtls_server_sessions[1].nx_secure_dtls_session_in_use))
    {
        ERROR_COUNTER();
    }
}

/* A cookie is accepted only from the source it was issued to, for the same ClientHello,
   unaltered. The session allocated then continues from the ClientHello's sequence
   numbers.  */
static VOID test_cookie_binding(VOID)
{
UCHAR clienthello[CLIENTHELLO_MAX];
UCHAR cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR altered[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR reissued[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR reply[1500];
UINT  length;
UINT  reply_length;
NX_SECURE_DTLS_SESSION *session;

    raw_rebind(RAW_PORT + 20);
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    clienthello_expect_hvr(clienthello, length, cookie);

    /* The same cookie from another port.  */
    raw_rebind(RAW_PORT + 21);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);
    raw_rebind(RAW_PORT + 20);

    /* One byte of the MAC altered.  */
    memcpy(altered, cookie, sizeof(altered));
    altered[5] ^= 0x01;
    length = clienthello_build(clienthello, 0, 1, 1, 0, altered, NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);

    /* A key identifier the server never issues.  */
    memcpy(altered, cookie, sizeof(altered));
    altered[0] = 2;
    length = clienthello_build(clienthello, 0, 1, 1, 0, altered, NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);

    /* A different random.  */
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, NX_SECURE_DTLS_COOKIE_LENGTH, 0x33);
    clienthello_expect_hvr(clienthello, length, reissued);

    /* A truncated cookie.  */
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, NX_SECURE_DTLS_COOKIE_LENGTH - 1, 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);

    if (server_connect_count != 0)
    {
        ERROR_COUNTER();
    }

    /* The valid cookie, as record sequence 0x000100000005 and message sequence 1.  */
    length = clienthello_build(clienthello, 1, 5, 1, 0, cookie, NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);
    raw_send(clienthello, length);
    if (tx_semaphore_get(&semaphore_connect, NX_IP_PERIODIC_RATE) || (server_connect_count != 1))
    {
        ERROR_COUNTER();
        return;
    }

    session = connect_session[0];
    if ((session -> nx_secure_dtls_cookie_verified != NX_TRUE) ||
        (session -> nx_secure_dtls_expected_handshake_sequence != 1) ||
        (session -> nx_secure_dtls_local_handshake_sequence != 1) ||
        (session -> nx_secure_dtls_tls_session.nx_secure_tls_local_sequence_number[1] != 1) ||
        (session -> nx_secure_dtls_tls_session.nx_secure_tls_local_sequence_number[0] != 5))
    {
        ERROR_COUNTER();
    }

    /* The server answers the queued ClientHello with a ServerHello, which follows the
       HelloVerifyRequest in both record and message sequence.  */
    nx_secure_dtls_server_session_start(session, NX_IP_PERIODIC_RATE / 2);

    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    if ((reply_length < 25) || (reply[0] != 0x16) || memcmp(&reply[3], &clienthello[3], 8) ||
        (reply[13] != 0x02) || (reply[17] != 0) || (reply[18] != 1))
    {
        ERROR_COUNTER();
    }

    if (session -> nx_secure_dtls_cookie_verified != NX_FALSE)
    {
        ERROR_COUNTER();
    }

    nx_secure_dtls_session_reset(session);
    while (raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE / 5))
    {
    }
}

/* With every session in use, a ClientHello returning a valid cookie is refused with an
   internal_error alert and reported to the application.  */
static VOID test_no_free_session(VOID)
{
UCHAR clienthello[CLIENTHELLO_MAX];
UCHAR reply[256];
UINT  length;
UINT  reply_length;
UINT  i;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;
NXD_ADDRESS address;

    for (i = 0; i < NUM_SERVER_SESSIONS; i++)
    {
        raw_rebind(RAW_PORT + 30 + i);
        cookie_exchange(0, 1, 1);
        if (tx_semaphore_get(&semaphore_connect, NX_IP_PERIODIC_RATE))
        {
            ERROR_COUNTER();
        }
    }

    raw_rebind(RAW_PORT + 40);
    server_error_count = 0;
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    raw_send(clienthello, length);
    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    if ((reply_length != 15) || (reply[0] != NX_SECURE_TLS_ALERT) || (reply[13] != NX_SECURE_TLS_ALERT_LEVEL_FATAL) ||
        (reply[14] != NX_SECURE_TLS_ALERT_INTERNAL_ERROR) || (server_error_count != 1) ||
        (server_error_code != NX_SECURE_TLS_NO_FREE_DTLS_SESSIONS))
    {
        ERROR_COUNTER();
    }

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    if (direct_check(clienthello, length, 0, &address, RAW_PORT, NX_IP_VERSION_V4, NX_NULL, &hello_info) !=
        NX_SECURE_TLS_NO_FREE_DTLS_SESSIONS)
    {
        ERROR_COUNTER();
    }

    if (server_connect_count != 1 + NUM_SERVER_SESSIONS)
    {
        ERROR_COUNTER();
    }

    for (i = 0; i < NUM_SERVER_SESSIONS; i++)
    {
        nx_secure_dtls_session_reset(&dtls_server.nx_dtls_server_sessions[i]);
    }
}

/* A NetX Secure DTLS client completes a handshake through the cookie exchange.  */
static VOID test_client_handshake(VOID)
{
UINT                    status;
NX_SECURE_DTLS_SESSION *session;

    tx_thread_resume(&client_thread);

    if (tx_semaphore_get(&semaphore_connect, 5 * NX_IP_PERIODIC_RATE))
    {
        ERROR_COUNTER();
        return;
    }

    session = connect_session[(server_connect_count - 1) & 0x07];
    status = nx_secure_dtls_server_session_start(session, 5 * NX_IP_PERIODIC_RATE);
    if (status)
    {
        ERROR_COUNTER();
    }

    if ((tx_semaphore_get(&semaphore_client, 5 * NX_IP_PERIODIC_RATE)) || (client_status != NX_SUCCESS) ||
        (session -> nx_secure_dtls_cookie_verified != NX_FALSE))
    {
        ERROR_COUNTER();
    }

    nx_secure_dtls_session_reset(session);
}

/* A cookie verifies under the current secret, and under the one before it until that is
   replaced in turn or two lifetimes pass without a ClientHello.  */
static VOID test_rotation(VOID)
{
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       cookie_a[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       cookie_b[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       cookie_c[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       cookie_d[NX_SECURE_DTLS_COOKIE_LENGTH];
UINT        length;
ULONG       start = 1000000;
NXD_ADDRESS address;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;

    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
    tx_time_set(start);

    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    memcpy(cookie_a, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(cookie_a));
    if ((cookie_a[0] != 0) || (hello_info.nx_secure_dtls_clienthello_cookie_length != NX_SECURE_DTLS_COOKIE_LENGTH))
    {
        ERROR_COUNTER();
    }

    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie_a, sizeof(cookie_a), 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }

    /* Within the first lifetime.  */
    tx_time_set(start + LIFETIME - 1);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }

    /* First rotation: cookie_a is now under the previous secret.  */
    tx_time_set(start + LIFETIME);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    memcpy(cookie_b, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(cookie_b));
    if (cookie_b[0] != 1)
    {
        ERROR_COUNTER();
    }

    /* Second rotation: cookie_a's secret is replaced, cookie_b's becomes the previous.  */
    tx_time_set(start + 2 * LIFETIME);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie_b, sizeof(cookie_b), 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie_a, sizeof(cookie_a), 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    memcpy(cookie_c, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(cookie_c));
    if (cookie_c[0] != 0)
    {
        ERROR_COUNTER();
    }

    /* Two lifetimes without a ClientHello: only a cookie under the new secret verifies.  */
    tx_time_set(start + 4 * LIFETIME);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie_c, sizeof(cookie_c), 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    memcpy(cookie_d, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(cookie_d));
    if ((cookie_d[0] != 1) || (dtls_server.nx_dtls_server_cookie_previous_valid != NX_FALSE))
    {
        ERROR_COUNTER();
    }
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie_d, sizeof(cookie_d), 0x32);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }

    /* The same cookie for another client port, server port or address.  */
    if (direct_check(clienthello, length, 0, &address, 7001, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS + 1;
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;

    /* The same cookie with another cipher suite list.  */
    clienthello[length - 3] = 0x0a;
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
}

/* Cookies are HMAC-SHA256 of the peer and the ClientHello parameters, keyed by 32 bytes
   drawn from NX_RAND, or by secrets derived from the application's secret as
   HMAC-SHA256(secret, counter).  */
static VOID test_secret_construction(VOID)
{
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       secret[32];
UCHAR       master[32];
UCHAR       counter[4] = {0, 0, 0, 0};
UCHAR       expected[NX_SECURE_DTLS_COOKIE_LENGTH];
UINT        length;
UINT        i;
UINT        random_value;
ULONG       start = 3000000;
NXD_ADDRESS address;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    tx_time_set(start);

    /* Secret drawn from NX_RAND.  */
    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
    srand(1234);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    srand(1234);
    for (i = 0; i < 32; i += 4)
    {
        random_value = (UINT)rand();
        secret[i] = (UCHAR)(random_value >> 24);
        secret[i + 1] = (UCHAR)(random_value >> 16);
        secret[i + 2] = (UCHAR)(random_value >> 8);
        secret[i + 3] = (UCHAR)random_value;
    }
    cookie_expected(secret, 0, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

    /* Secrets derived from the application's secret.  */
    for (i = 0; i < sizeof(master); i++)
    {
        master[i] = (UCHAR)i;
    }
    if (_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, master, sizeof(master)))
    {
        ERROR_COUNTER();
    }
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    hmac_sha256(master, sizeof(master), counter, sizeof(counter), secret);
    cookie_expected(secret, 0, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

    /* The next secret takes the next counter value.  */
    tx_time_set(start + LIFETIME);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    counter[3] = 1;
    hmac_sha256(master, sizeof(master), counter, sizeof(counter), secret);
    cookie_expected(secret, 1, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

    /* A 16-byte application secret.  */
    if (_nxe_secure_dtls_server_cookie_secret_set(&dtls_server, master, 16))
    {
        ERROR_COUNTER();
    }
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    counter[3] = 0;
    hmac_sha256(master, 16, counter, sizeof(counter), secret);
    cookie_expected(secret, 0, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

    /* Back to NX_RAND.  */
    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
    srand(99);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    srand(99);
    for (i = 0; i < 32; i += 4)
    {
        random_value = (UINT)rand();
        secret[i] = (UCHAR)(random_value >> 24);
        secret[i + 1] = (UCHAR)(random_value >> 16);
        secret[i + 2] = (UCHAR)(random_value >> 8);
        secret[i + 3] = (UCHAR)random_value;
    }
    cookie_expected(secret, 0, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

#ifdef FEATURE_NX_IPV6
    /* An IPv6 peer, received on an address whose index is known or not.  */
    address.nxd_ip_version = NX_IP_VERSION_V6;
    address.nxd_ip_address.v6[0] = 0x20010db8;
    address.nxd_ip_address.v6[1] = 0x01020304;
    address.nxd_ip_address.v6[2] = 0x05060708;
    address.nxd_ip_address.v6[3] = 0x090a0b0c;
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    if ((direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V6, NX_NULL, &hello_info) != NX_CONTINUE) ||
        (hello_info.nx_secure_dtls_clienthello_address_index != 0xFFFFFFFF))
    {
        ERROR_COUNTER();
    }
    cookie_expected(secret, 0, &address, 7000, SERVER_PORT, clienthello, expected);
    if (memcmp(expected, hello_info.nx_secure_dtls_clienthello_cookie, sizeof(expected)))
    {
        ERROR_COUNTER();
    }
    if ((direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V6, &server_ip.nx_ipv6_address[1],
                      &hello_info) != NX_CONTINUE) ||
        (hello_info.nx_secure_dtls_clienthello_address_index != server_ip.nx_ipv6_address[1].nxd_ipv6_address_index))
    {
        ERROR_COUNTER();
    }
#endif /* FEATURE_NX_IPV6 */
}

/* Malformed or truncated ClientHellos are dropped by the cookie check.  */
static VOID test_parser(VOID)
{
UCHAR       base[CLIENTHELLO_MAX];
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UINT        length;
UINT        status;
NXD_ADDRESS address;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    length = clienthello_build(base, 0, 0, 0, 0, NX_NULL, 0, 0x32);

#define PARSE_EXPECT(data, data_length, extra, expected)                                            \
    status = direct_check((data), (data_length), (extra), &address, 7000, NX_IP_VERSION_V4, NX_NULL, \
                          &hello_info);                                                             \
    if (status != (expected))                                                                       \
    {                                                                                               \
        ERROR_COUNTER();                                                                            \
    }
#define PARSE_DROPPED(data, data_length, extra)                                                     \
    status = direct_check((data), (data_length), (extra), &address, 7000, NX_IP_VERSION_V4, NX_NULL, \
                          &hello_info);                                                             \
    if ((status == NX_SUCCESS) || (status == NX_CONTINUE))                                          \
    {                                                                                               \
        ERROR_COUNTER();                                                                            \
    }

    PARSE_EXPECT(base, length, 0, NX_CONTINUE);

    /* Shorter than the fixed part, or holding less than its length claims.  */
    PARSE_DROPPED(base, 59, 0);
    PARSE_DROPPED(base, 0, length);

    /* Each header field out of range.  */
    memcpy(clienthello, base, length);
    clienthello[0] = 0x17;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[1] = 0x03;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[3] = 1;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[4] = 1;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[12] = (UCHAR)(clienthello[12] + 1);
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[12] = 11;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[13] = 0x02;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[21] = 1;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[24] = (UCHAR)(clienthello[24] - 1);
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[16] = (UCHAR)(clienthello[16] + 1);
    clienthello[24] = (UCHAR)(clienthello[24] + 1);
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[59] = 33;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[16] = 35;
    clienthello[24] = 35;
    PARSE_DROPPED(clienthello, length, 0);

    /* Each length of the body walk out of range, or past the data held.  */
    PARSE_DROPPED(base, 60, length - 60);
    memcpy(clienthello, base, length);
    clienthello[60] = 200;
    PARSE_DROPPED(clienthello, length, 0);
    PARSE_DROPPED(base, 61, length - 61);
    memcpy(clienthello, base, length);
    clienthello[61] = 0;
    clienthello[62] = 0;
    PARSE_DROPPED(clienthello, length, 0);
    memcpy(clienthello, base, length);
    clienthello[61] = 1;
    PARSE_DROPPED(clienthello, length, 0);
    PARSE_DROPPED(base, 71, length - 71);
    memcpy(clienthello, base, length);
    clienthello[71] = 5;
    PARSE_DROPPED(clienthello, length, 0);

    /* A cookie of the issued length, held only in part.  */
    memset(cookie, 0, sizeof(cookie));
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    PARSE_DROPPED(clienthello, 61, length - 61);

    /* A cookie of another length, and a 32-byte session ID hashed in two blocks.  */
    length = clienthello_build(clienthello, 0, 1, 1, 32, cookie, 5, 0x32);
    PARSE_EXPECT(clienthello, length, 0, NX_CONTINUE);

#undef PARSE_EXPECT
#undef PARSE_DROPPED
}

/* A cookie MAC that cannot be computed drops the ClientHello.  */
static VOID test_crypto_failures(VOID)
{
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       clienthello_plain[CLIENTHELLO_MAX];
UCHAR       master[32];
UINT        length;
UINT        plain_length;
UINT        status;
UINT        i;
NXD_ADDRESS address;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;
NX_SECURE_TLS_CRYPTO *original_table = dtls_server.nx_dtls_server_sessions[0].nx_secure_dtls_tls_session.nx_secure_tls_crypto_table;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);

    /* A current cookie, for the verification path.  */
    plain_length = clienthello_build(clienthello_plain, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    if (direct_check(clienthello_plain, plain_length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    length = clienthello_build(clienthello, 0, 1, 1, 0, hello_info.nx_secure_dtls_clienthello_cookie,
                               NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);

    memcpy(&fake_crypto_table, original_table, sizeof(fake_crypto_table));
    server_crypto_table_set(&fake_crypto_table);

    for (i = 0; i < 8; i++)
    {
        memcpy(&fake_hash_method, &crypto_method_sha256, sizeof(fake_hash_method));
#if (NX_SECURE_TLS_TLS_1_2_ENABLED)
        fake_crypto_table.nx_secure_tls_handshake_hash_sha256_method = &fake_hash_method;
#else
        fake_crypto_table.nx_secure_tls_handshake_hash_sha1_method = &fake_hash_method;
#endif
        switch (i)
        {
        case 0:
#if (NX_SECURE_TLS_TLS_1_2_ENABLED)
            fake_crypto_table.nx_secure_tls_handshake_hash_sha256_method = NX_NULL;
#else
            fake_crypto_table.nx_secure_tls_handshake_hash_sha1_method = NX_NULL;
#endif
            break;
        case 1:
            fake_hash_method.nx_crypto_init = NX_NULL;
            break;
        case 2:
            fake_hash_method.nx_crypto_operation = NX_NULL;
            break;
        case 3:
            fake_hash_method.nx_crypto_metadata_area_size = 0xFFFFFFFF;
            break;
        case 4:
            fake_hash_method.nx_crypto_block_size_in_bytes = 128;
            break;
        case 5:
            fake_hash_method.nx_crypto_ICV_size_in_bits = 520;
            break;
        case 6:
            fake_hash_method.nx_crypto_init = fake_init_fail;
            break;
        default:
            fake_hash_method.nx_crypto_operation = fake_operation_fail;
            break;
        }

        /* Verifying the client's cookie, then issuing one.  */
        status = direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info);
        if ((status == NX_SUCCESS) || (status == NX_CONTINUE))
        {
            ERROR_COUNTER();
        }
        status = direct_check(clienthello_plain, plain_length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL,
                              &hello_info);
        if ((status == NX_SUCCESS) || (status == NX_CONTINUE))
        {
            ERROR_COUNTER();
        }
    }

    /* Deriving a secret from the application's secret fails, and is retried.  */
    for (i = 0; i < sizeof(master); i++)
    {
        master[i] = (UCHAR)(i + 1);
    }
    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, master, sizeof(master));
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    status = direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info);
    if ((status == NX_SUCCESS) || (status == NX_CONTINUE) || (dtls_server.nx_dtls_server_cookie_ready != NX_FALSE))
    {
        ERROR_COUNTER();
    }
#if (NX_SECURE_TLS_TLS_1_2_ENABLED)
    fake_crypto_table.nx_secure_tls_handshake_hash_sha256_method = NX_NULL;
#else
    fake_crypto_table.nx_secure_tls_handshake_hash_sha1_method = NX_NULL;
#endif
    status = direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info);
    if ((status == NX_SUCCESS) || (status == NX_CONTINUE) || (dtls_server.nx_dtls_server_cookie_ready != NX_FALSE))
    {
        ERROR_COUNTER();
    }

    server_crypto_table_set(original_table);
    if (direct_check(clienthello, length, 0, &address, 7000, NX_IP_VERSION_V4, NX_NULL, &hello_info) != NX_CONTINUE)
    {
        ERROR_COUNTER();
    }
    _nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
}

/* HelloVerifyRequest transmission failures release the packet.  */
static VOID test_helloverifyrequest_send(VOID)
{
UCHAR           clienthello[CLIENTHELLO_MAX];
UCHAR           reply[256];
UINT            length;
NXD_ADDRESS     address;
NX_PACKET      *small_packets[2];
NX_PACKET_POOL *original_pool = server_ip.nx_ip_default_packet_pool;
NX_SECURE_DTLS_CLIENTHELLO_INFO hello_info;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    raw_rebind(RAW_PORT + 50);
    length = clienthello_build(clienthello, 0, 9, 3, 0, NX_NULL, 0, 0x32);
    if (direct_check(clienthello, length, 0, &address, RAW_PORT + 50, NX_IP_VERSION_V4, NX_NULL, &hello_info) !=
        NX_CONTINUE)
    {
        ERROR_COUNTER();
    }

    /* Sent through routing when the receiving address is not known.  */
    hello_info.nx_secure_dtls_clienthello_address_index = 0xFFFFFFFF;
    if (_nx_secure_dtls_server_helloverifyrequest_send(&dtls_server.nx_dtls_server_udp_socket, &address,
                                                       RAW_PORT + 50, &hello_info) != NX_SUCCESS)
    {
        ERROR_COUNTER();
    }
    length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    helloverifyrequest_check(reply, length, clienthello, reply);

#ifdef FEATURE_NX_IPV6
    /* From an IPv6 address that is not valid.  */
    address.nxd_ip_version = NX_IP_VERSION_V6;
    address.nxd_ip_address.v6[0] = 0x20010db8;
    address.nxd_ip_address.v6[1] = 0;
    address.nxd_ip_address.v6[2] = 0;
    address.nxd_ip_address.v6[3] = 1;
    hello_info.nx_secure_dtls_clienthello_address_index = 0;
    if (_nx_secure_dtls_server_helloverifyrequest_send(&dtls_server.nx_dtls_server_udp_socket, &address,
                                                       RAW_PORT + 50, &hello_info) == NX_SUCCESS)
    {
        ERROR_COUNTER();
    }
    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
#endif /* FEATURE_NX_IPV6 */

    /* Packets too small for the record, then none.  */
    server_ip.nx_ip_default_packet_pool = &small_pool;
    if (_nx_secure_dtls_server_helloverifyrequest_send(&dtls_server.nx_dtls_server_udp_socket, &address,
                                                       RAW_PORT + 50, &hello_info) != NX_SECURE_TLS_PACKET_BUFFER_TOO_SMALL)
    {
        ERROR_COUNTER();
    }
    if (nx_packet_allocate(&small_pool, &small_packets[0], 0, NX_NO_WAIT) ||
        nx_packet_allocate(&small_pool, &small_packets[1], 0, NX_NO_WAIT))
    {
        ERROR_COUNTER();
    }
    if (_nx_secure_dtls_server_helloverifyrequest_send(&dtls_server.nx_dtls_server_udp_socket, &address,
                                                       RAW_PORT + 50, &hello_info) == NX_SUCCESS)
    {
        ERROR_COUNTER();
    }
    nx_packet_release(small_packets[0]);
    nx_packet_release(small_packets[1]);
    server_ip.nx_ip_default_packet_pool = original_pool;
}

static VOID test_thread_entry(ULONG thread_input)
{
UINT status;
UINT i;

    printf("NetX Secure Test:   DTLS Stateless Cookie Test.........................");

    server_dtls_setup();
    test_secret_set_api();

    status = nx_secure_dtls_server_start(&dtls_server);
    if (status)
    {
        ERROR_COUNTER();
    }

    status = nx_udp_socket_create(&client_ip, &raw_socket, "Raw socket", NX_IP_NORMAL,
                                  NX_DONT_FRAGMENT, 0x80, 16);
    status |= nx_udp_socket_bind(&raw_socket, RAW_PORT, NX_NO_WAIT);
    if (status)
    {
        ERROR_COUNTER();
    }

    test_drops();
    test_exhaustion();
    test_cookie_binding();
    test_no_free_session();
    test_client_handshake();
    test_rotation();
    test_secret_construction();
    test_parser();
    test_crypto_failures();
    test_helloverifyrequest_send();

    /* Resetting a session clears its verified mark.  */
    dtls_server.nx_dtls_server_sessions[0].nx_secure_dtls_cookie_verified = NX_TRUE;
    nx_secure_dtls_session_reset(&dtls_server.nx_dtls_server_sessions[0]);
    if (dtls_server.nx_dtls_server_sessions[0].nx_secure_dtls_cookie_verified != NX_FALSE)
    {
        ERROR_COUNTER();
    }

    nx_udp_socket_unbind(&raw_socket);
    nx_udp_socket_delete(&raw_socket);

    tx_thread_sleep(NX_IP_PERIODIC_RATE);

    nx_secure_dtls_server_stop(&dtls_server);
    nx_secure_dtls_server_delete(&dtls_server);

    /* Deleting the server clears its cookie secrets.  */
    for (i = 0; i < NX_SECURE_DTLS_COOKIE_SECRET_SIZE; i++)
    {
        if (dtls_server.nx_dtls_server_cookie_secret[0][i] || dtls_server.nx_dtls_server_cookie_secret[1][i])
        {
            ERROR_COUNTER();
            break;
        }
    }
    if (dtls_server.nx_dtls_server_cookie_ready != NX_FALSE)
    {
        ERROR_COUNTER();
    }

    if ((server_pool.nx_packet_pool_available != server_pool.nx_packet_pool_total) ||
        (client_pool.nx_packet_pool_available != client_pool.nx_packet_pool_total) ||
        (direct_pool.nx_packet_pool_available != direct_pool.nx_packet_pool_total) ||
        (small_pool.nx_packet_pool_available != small_pool.nx_packet_pool_total))
    {
        ERROR_COUNTER();
    }

    if (error_counter)
    {
        printf("ERROR!\n");
        test_control_return(1);
    }
    else
    {
        printf("SUCCESS!\n");
        test_control_return(0);
    }
}

static VOID client_thread_entry(ULONG thread_input)
{
UINT        status;
NXD_ADDRESS server_address;

    server_address.nxd_ip_version = NX_IP_VERSION_V4;
    server_address.nxd_ip_address.v4 = TEST_SERVER_IP_ADDRESS;

    status = nx_udp_socket_create(&client_ip, &client_socket, "Client socket", NX_IP_NORMAL,
                                  NX_DONT_FRAGMENT, 0x80, 5);
    status |= nx_udp_socket_bind(&client_socket, NX_ANY_PORT, NX_NO_WAIT);
    status |= nx_secure_dtls_session_create(&dtls_client_session, &nx_crypto_tls_ciphers,
                                            client_metadata, sizeof(client_metadata),
                                            client_tls_packet_buffer, sizeof(client_tls_packet_buffer),
                                            1, client_cert_buffer, sizeof(client_cert_buffer));
    status |= nx_secure_x509_certificate_initialize(&client_trusted_ca, test_ca_cert_der, test_ca_cert_der_len,
                                                    NX_NULL, 0, NULL, 0, NX_SECURE_X509_KEY_TYPE_NONE);
    status |= nx_secure_dtls_session_trusted_certificate_add(&dtls_client_session, &client_trusted_ca, 1);
#if defined(NX_SECURE_ENABLE_PSK_CIPHERSUITES) || defined(NX_SECURE_ENABLE_ECJPAKE_CIPHERSUITE)
    status |= nx_secure_dtls_psk_add(&dtls_client_session, PSK, strlen(PSK),
                                     PSK_IDENTITY, strlen(PSK_IDENTITY), PSK_HINT, strlen(PSK_HINT));
#endif
    if (status)
    {
        ERROR_COUNTER();
    }

    client_status = nx_secure_dtls_client_session_start(&dtls_client_session, &client_socket, &server_address,
                                                        SERVER_PORT, 5 * NX_IP_PERIODIC_RATE);
    tx_semaphore_put(&semaphore_client);

    nx_secure_dtls_session_end(&dtls_client_session, NX_NO_WAIT);
    nx_secure_dtls_session_delete(&dtls_client_session);
    nx_udp_socket_unbind(&client_socket);
    nx_udp_socket_delete(&client_socket);
}

